def main():
    backup = BASE / 'review/before_style_edit'
    backup.mkdir(exist_ok=True)
    for filename, changes in CHANGES.items():
        path = SECTIONS / filename
        if not (backup / filename).exists():
            shutil.copyfile(path, backup / filename)
        lines = path.read_text(encoding='utf-8').splitlines()
        for prefix, replacement in changes:
            matches = [i for i, line in enumerate(lines) if line.startswith(prefix)]
            if len(matches) != 1:
                raise ValueError((filename, prefix, matches))
            lines[matches[0]] = replacement
        # Fix punctuation only; table cells and numeric measurements stay intact.
        text = '\n'.join(lines) + '\n'
        text = re.sub(r'(?<!\\)%', r'\\%', text)
        path.write_text(text, encoding='utf-8')
    # Synchronize the manuscript builder without regenerating or resetting the declaration.
    builder = BASE / 'write_report.py'
    text = builder.read_text(encoding='utf-8')
    node = next(n for n in ast.parse(text).body if isinstance(n, ast.Assign) and any(isinstance(t, ast.Name) and t.id == 'PAGES' for t in n.targets))
    lines = text.splitlines(keepends=True)
    pages = [p.read_text(encoding='utf-8').strip() for p in sorted(SECTIONS.glob('page*.tex'))]
    replacement = 'PAGES = [\n' + ',\n'.join("r'''" + p + "'''" for p in pages) + '\n]\n'
    builder.write_text(''.join(lines[:node.lineno-1]) + replacement + ''.join(lines[node.end_lineno:]), encoding='utf-8')
    print('Revised', sum(map(len, CHANGES.values())), 'prose blocks; tables, citations and required section titles preserved.')


if __name__ == '__main__':
    main()
